// @ppm--dependency--config.profile--logo--default

// Central brand config for the CMS (login page + dashboard shell).
// Dropping this folder into a new project? Replace these strings and/or the
// imported logo. If you don't have a logo yet, set `logo: null` and the UI
// automatically falls back to a yellow "CMS"-style text badge built from
// `shortName`.

import { BUSINESS_NAME } from "./profile--business-name";
import { LOGO_DEFAULT } from "./profile--logo--default";




export type CmsBranding = {
  /** Imported image (e.g. `import logo from "./logo.png"`) or null to
   *  use the text fallback derived from `shortName`. */
  logo: string | null;

  /** Short brand used by the text fallback badge (2–4 chars reads best). */
  shortName: string;

  /** Long brand shown on the login left panel. */
  name: string;

  /** Supporting line shown under `name` on the login left panel. */
  tagline: string;

  /** Small copy under the login card title. */
  cardSubtitle: string;
};

export const BRANDING: CmsBranding = {
  shortName: "CMS",
  tagline: "Content Management System",
  cardSubtitle: "Sign in to your CMS account",
  name: BUSINESS_NAME,
  logo: LOGO_DEFAULT,
};
